use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut list: VecDeque<i64> = VecDeque::new();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for line in input.lines() {
        let mut parts = line.split_whitespace();
        let cmd = match parts.next() {
            Some(c) => c,
            None => continue,
        };
        let arg = parts.next();

        match cmd {
            "push_front" => {
                if let Some(x) = arg.and_then(|s| s.parse::<i64>().ok()) {
                    list.push_front(x);
                }
            }
            "push_back" => {
                if let Some(x) = arg.and_then(|s| s.parse::<i64>().ok()) {
                    list.push_back(x);
                }
            }
            "pop_front" => match list.pop_front() {
                Some(x) => writeln!(out, "{}", x).unwrap(),
                None => writeln!(out, "empty").unwrap(),
            },
            "pop_back" => match list.pop_back() {
                Some(x) => writeln!(out, "{}", x).unwrap(),
                None => writeln!(out, "empty").unwrap(),
            },
            "remove" => {
                let x = arg.and_then(|s| s.parse::<i64>().ok());
                let pos = x.and_then(|x| list.iter().position(|&v| v == x));
                match pos {
                    Some(i) => {
                        list.remove(i);
                        writeln!(out, "removed").unwrap();
                    }
                    None => writeln!(out, "missing").unwrap(),
                }
            }
            "reverse" => {
                let v: Vec<i64> = list.drain(..).rev().collect();
                list = VecDeque::from(v);
            }
            "print" => {
                if list.is_empty() {
                    writeln!(out, "<empty>").unwrap();
                } else {
                    let s: Vec<String> = list.iter().map(|x| x.to_string()).collect();
                    writeln!(out, "{}", s.join(" ")).unwrap();
                }
            }
            "nth" => {
                let k = arg.and_then(|s| s.parse::<usize>().ok());
                match k.and_then(|k| list.get(k)) {
                    Some(x) => writeln!(out, "{}", x).unwrap(),
                    None => writeln!(out, "none").unwrap(),
                }
            }
            _ => {}
        }
    }
}
